+	// `.item` on `$(...)`/`$input`; the legacy `$node[...]` members are the
+	// item's own `json`/`binary`, not an item.
+	if (node.object.kind === 'nodeRef' && node.object.ref !== 'legacy') return assertItem(value);
+
 	return value;
 }

@@ -510,7 +514,32 @@ function evalNodeRefCall(proxy: unknown, method: string, env: Env): unknown {
 	const result = bounded(fn.call(proxy));
 	env.charge(isArray(result) ? result.length : 1);

-	return result;
+	return method === 'all' ? assertItems(result) : assertItem(result);
+}
+
+/**
+ * A node reference yields an item (`{ json, ... }`) or, from `all()`, an
+ * array of them. Anything else (no item at all, or combined binary mode,
+ * where the proxy hands back the item's `json` in its place) is not what
+ * parsing assumed, so the engine decides what it yields.
+ */
+const isItem = (value: unknown): boolean =>
+	isObj(value) &&
+	!isArray(value) &&
+	hasOwn(value, 'json') &&
+	isObj(value.json) &&
+	!isArray(value.json);
+
+function assertItem(value: unknown): unknown {
+	if (!isItem(value)) throw new EngineFallbackError();
+
+	return value;
+}
+
+function assertItems(value: unknown): unknown {
+	if (!isArray(value) || !value.every(isItem)) throw new EngineFallbackError();
+
+	return value;
 }

